import assert from 'node:assert/strict';
import {createGardenState,stepGarden,restoreGardenState} from '../../../../src/js/garden/GardenSimulation.js';
import {GARDEN as C} from '../../../../src/js/garden/GardenLevel.js';
import {createPilot} from './piloto.mjs';
const irregular=process.argv.includes('--irregular');
for(const difficulty of ['NORMAL','EASY']){
 const state=createGardenState(difficulty),pilot=createPilot();let previous=state.player.x,idle=0,recovered=0,jumps=0;
 for(let tick=0;state.time<1800&&!['GAME_OVER','COMPLETE'].includes(state.stage);tick++){
  const dt=irregular?[1/120,1/30,.02,.05][tick%4]:1/60;
  const events=stepGarden(state,pilot(state),dt,difficulty);recovered+=events.filter(e=>e.type==='rescue'||e.type==='dazed').length;jumps+=events.filter(e=>e.type==='jump').length;
  if(Math.abs(state.player.x-previous)<.2)idle+=dt;else idle=0;previous=state.player.x;
  if(tick%18000===0)console.log('PROGRESSO',difficulty,Math.round(state.time),Math.round(state.player.x),state.player.support,state.hp);
  if(idle>18){console.log('BLOQUEIO',JSON.stringify({x:state.player.x,y:state.player.y,support:state.player.support,time:state.time,hp:state.hp}));break;}
 }
 console.log(JSON.stringify({difficulty,irregular,stage:state.stage,minutes:state.time/60,x:state.player.x,goal:C.goal,hp:state.hp,recovered,jumps,defeated:state.defeated}));
 assert.ok(state.time/60>18&&state.time/60<22,'Duração automatizada próxima de vinte minutos');
 assert.equal(state.stage,'COMPLETE','Percurso contínuo chega ao piquenique');assert.equal(restoreGardenState(JSON.parse(JSON.stringify(state)),difficulty).stage,'COMPLETE');
}
